import org.formasaloido.*;import java.util.*;

public final class MathExplorationChecks {
 static int checks;static void check(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
 static void same(Sound.Program a,Sound.Program b){check(a.spans.size()==b.spans.size(),"Shared scan span count");check(a.duration==b.duration,"Shared scan duration");for(int i=0;i<a.spans.size();i++){Sound.Span x=a.spans.get(i),y=b.spans.get(i);check(x.kind.equals(y.kind)&&x.a.distance(y.a)<1e-8&&x.b.distance(y.b)<1e-8&&x.gain==y.gain,"Same scan geometry and gain");}}
 public static void main(String[] args){Sound.Settings settings=new Sound.Settings();TouchMap map=new TouchMap();Geometry g=MathExploration.geometry(0,0);for(Geometry.Point edge:Curriculum.points(0,100,600,100,300,0,300,450)){TouchMap.Feedback f=map.sample(g,edge,0,0,18,true);check(f.frame&&f.kind.equals("frame"),"All canvas borders reachable");check(MathExploration.at(0,edge).contains("Marco"),"Frame announced");}
  Geometry.Point empty=new Geometry.Point(550,380);check(map.sample(g,empty,0,0,18,true).kind.equals("air"),"Empty-space reference restored outside graduated grid");check(map.sample(g,empty,0,0,18,false).kind.equals("silent"),"Air can be disabled");check(MathExploration.at(0,empty).contains("Zona de referencia"),"Outer reference zone is not rejected");check(map.sample(g,new Geometry.Point(220,105),0,0,18,true).kind.equals("vertex"),"Math point contact");check(map.sample(g,new Geometry.Point(280,100),0,0,6,false).kind.equals("silent"),"Small contact tolerance");check(map.sample(g,new Geometry.Point(280,100),0,0,35,false).kind.equals("line"),"Inherited tolerance applied");
  check(new TouchMap().sample(MathExploration.geometry(2,1),new Geometry.Point(220,265),1,0,18,true).kind.equals("region"),"Shared region fill");check(new TouchMap().sample(MathExploration.geometry(2,1),new Geometry.Point(550,380),2,0,18,false).kind.equals("region"),"Shared negative surface");
  for(int kind=0;kind<8;kind++){check(MathExploration.geometry(kind,2).shapes.size()==2,"Axes-only filter");check(MathExploration.geometry(kind,1).shapes.size()==MathLesson.plane(kind).shapes.size()-2,"Figure-only filter");for(int mode=0;mode<5;mode++){if(mode==3&&kind!=2&&kind!=3)continue;for(Geometry.Point origin:Curriculum.points(0,0,600,0,600,450,0,450,300,225)){MathExploration.Scan scan=MathExploration.scan(kind,0,settings,mode,origin,40,-1,false);check(scan.program.duration>0&&scan.program.duration<=180.000001,"Bounded nonempty math scan");if(mode==4)same(scan.program,ImageScan.contour(MathLesson.plane(kind),settings,origin));else{ImageScan reference=new ImageScan(MathLesson.plane(kind),null,settings,mode,origin,40,128,255,false);same(scan.program,reference.program(settings,-1));check(scan.count==reference.sections.size(),"Same image scan sections");}}}}
  MathExploration.Scan quad=MathExploration.scan(2,1,settings,2,new Geometry.Point(0,0),40,3,true);check(quad.count==4&&quad.description.contains("Inferior izquierdo"),"Quadrant ordering and selected section");try{MathExploration.scan(4,1,settings,3,new Geometry.Point(0,0),40,-1,false);throw new AssertionError("Open curve has no fill");}catch(IllegalArgumentException expected){checks++;}try{MathExploration.scan(2,0,settings,0,new Geometry.Point(0,0),40,99,false);throw new AssertionError("Scan section bounds");}catch(IllegalArgumentException expected){checks++;}
  check(MathExploration.frame(settings).spans.stream().anyMatch(s->s.kind.equals("closed")),"Frame closure marker");check(MathExploration.reference(settings).duration>1,"Orientation reference");System.out.println("PASS "+checks+" math exploration checks: frame, air, contact, fill, negative, filters and identical shared image scans.");
 }
}
